# 1. 闭包陷阱演示
# 陷阱：延迟绑定
funcs = []
for i in range(3):
    funcs.append(lambda: i)

for f in funcs:
    print(f())  # 2 2 2（不是 0 1 2）

# 修复方式 1：默认参数
def create_funcs_1():
    return [lambda x=i: x for i in range(3)]

# 修复方式 2：立即执行的函数表达式
funcs2 = [(lambda j: lambda: j)(j) for j in range(3)]
for f in funcs2:
    print(f())  # 0 1 2

# 修复方式 3：functools.partial
from functools import partial
funcs3 = [partial(lambda x: x, i) for i in range(3)]

# 2. 闭包实现记忆化
def memoize(func):
    cache = {}
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    return wrapper

@memoize
def fib(n):
    if n < 2:
        return n
    return fib(n-1) + fib(n-2)

